package com.fakrudeenmart.servlet;
import com.fakrudeenmart.model.UserRole; import com.fakrudeenmart.service.AdminService;
import javax.servlet.ServletException; import javax.servlet.http.*; import java.io.IOException;
public class AdminUserDetailsServlet extends HttpServlet { private AdminService service; public void init(){service=new AdminService();} protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{boolean buyer=req.getRequestURI().contains("/buyers/");long uid=AdminServletSupport.id(req.getParameter("id"),buyer?"Buyer was not found.":"Seller was not found.");if(buyer){req.setAttribute("user",service.getBuyer(AdminServletSupport.adminId(req),uid));req.setAttribute("buyerStats",service.getBuyerStats(AdminServletSupport.adminId(req),uid));req.setAttribute("orders",service.getBuyerOrders(AdminServletSupport.adminId(req),uid));}else{req.setAttribute("user",service.getSeller(AdminServletSupport.adminId(req),uid));req.setAttribute("sellerStats",service.getSellerStats(AdminServletSupport.adminId(req),uid));req.setAttribute("products",service.getSellerProducts(AdminServletSupport.adminId(req),uid));req.setAttribute("sellerOrders",service.getSellerOrders(AdminServletSupport.adminId(req),uid));}req.setAttribute("profileType",buyer?"buyer":"seller");req.getRequestDispatcher("/WEB-INF/views/admin/user-profile.jsp").forward(req,resp);} }
